function GlyphIcon({
  glyph,
  size,
  color,
}: {
  readonly glyph: ProviderGlyph;
  readonly size: number;
  readonly color: string;
}) {
  return (
    <Svg height={size} viewBox={glyph.viewBox} width={size}>
      {glyph.paths.map((path, index) => (
        <Path
          clipRule={path.clipRule}
          d={path.d}
          fill={path.fill ?? color}
          fillRule={path.fillRule}
          key={index}
          opacity={path.opacity}
        />
      ))}
    </Svg>
  );
}

export const ProviderLogo = memo(function ProviderLogo({
  providerId,
  label,
  size = 22,
  color,
}: {
  readonly providerId: string | undefined;
  readonly label?: string;
  readonly size?: number;
  readonly color?: string;
}) {
  const palette = useGraftPalette();
  if (!providerId) return null;
  if (providerId === "antigravity") {
    return (
      <Image source={antigravityMark} style={{ width: size, height: size }} resizeMode="contain" />
    );
  }
  const glyph = PROVIDER_MARKS[providerId];
  const tint = color ?? palette.foreground;
  if (glyph) return <GlyphIcon color={tint} glyph={glyph} size={size} />;

  const logo = BRANDED_LOGOS[providerId];
  if (logo) {
    return (
      <View
        style={[
          styles.tile,
          {
            backgroundColor: logo.tile ?? palette.subtle,
            borderRadius: size * 0.225,
            height: size,
            width: size,
          },
        ]}
      >
        <GlyphIcon color={logo.color} glyph={logo} size={size * 0.7} />
      </View>
    );
  }

  const initial = (label ?? providerId).trim().codePointAt(0);
  const monogram = initial ? String.fromCodePoint(initial).toLocaleUpperCase() : "?";
  return (
    <View
      style={[
        styles.tile,
        {
          backgroundColor: palette.subtle,
          borderRadius: size * 0.225,
          height: size,
          width: size,
        },
      ]}
    >
      <Text
        style={[styles.monogram, { color: tint, fontSize: size * 0.5, lineHeight: size * 0.55 }]}
      >
        {monogram}
      </Text>
    </View>
  );
});

const styles = StyleSheet.create({
  tile: { alignItems: "center", justifyContent: "center", overflow: "hidden" },
  monogram: { fontWeight: "600", includeFontPadding: false },
});
